const DL_WINDOW_SCRIPT_ID = "628f803d-445b-4489-b579-ec3ae7dca75b";
/* 斗罗开局 · 存档（酒馆全局变量为主，本浏览器留一份备份）
 * 术语见 变量系统/CONTEXT.md：存档 ≠ 草稿 ≠ 开局记录。
 * 斗罗开局、斗罗创意工坊两个脚本都内嵌这一段，读写同一个全局变量，谁先启用都能用；格式改了两边一起改。
 *
 * 全局变量 斗罗存档 = { 版本: 1, 列表: [条目] }
 * 条目 = { id, 名, 时间: ISO, 草稿: {...}, 自动?: true, 来源?: { 作品: id, 作品名, 版本 } }
 *   自动：落笔成功后自动存的“上次开局”，只有一条，每次覆盖
 *   来源：从创意工坊导入的；卸载那个作品时一起删
 * 导出文件 = { 格式: '斗罗开局存档', 版本: 1, 名, 时间, 草稿 }
 * 上限 30 条（含自动那条）。草稿只做形状检查，缺字段由建档页 fillDraft 补默认值。
 */
const DL_SAVE = Object.freeze({ KEY: '斗罗存档', BACKUP: 'dl-saves-backup:v1', LIMIT: 30, AUTO: '上次开局', FORMAT: '斗罗开局存档', NAME_MAX: 40, DRAFT_MAX: 65536 });

function createSaveStore(io) {
  const K = DL_SAVE;
  const now = io.now || (() => new Date());
  const plainObj = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
  const copy = (v) => JSON.parse(JSON.stringify(v));

  function cleanName(name) {
    return String(name == null ? '' : name).replace(/[\u0000-\u001f\u007f]/gu, '').replace(/\s+/gu, ' ').trim().slice(0, K.NAME_MAX);
  }
  function checkDraft(d) {
    if (!plainObj(d)) return '存档里没有建档内容';
    let text;
    try { text = JSON.stringify(d); } catch (_) { return '存档内容读不出来'; }
    if (text.length > K.DRAFT_MAX) return '存档太大了（超过 64KB），不像是建档内容';
    if (d.部 != null && d.部 !== '' && !/^(斗[1-4]|神界|英雄)$/u.test(String(d.部))) return `存档里的“部”不对：${String(d.部).slice(0, 12)}`;
    return null;
  }
  function cleanItem(x) {
    if (!plainObj(x) || checkDraft(x.草稿)) return null;
    const out = { id: String(x.id || newId()), 名: cleanName(x.名) || '未命名', 时间: String(x.时间 || now().toISOString()), 草稿: copy(x.草稿) };
    if (x.自动) out.自动 = true;
    if (plainObj(x.来源) && x.来源.作品 != null) out.来源 = { 作品: String(x.来源.作品), 作品名: cleanName(x.来源.作品名) || '', 版本: Number(x.来源.版本) || 1 };
    return out;
  }
  function newId() { return 's' + now().getTime().toString(36) + Math.random().toString(36).slice(2, 7); }

  // ── 备份 ──
  function readBackup() {
    try { const t = io.storage && io.storage.getItem(K.BACKUP); const v = t ? JSON.parse(t) : null; return Array.isArray(v) ? v.map(cleanItem).filter(Boolean) : []; } catch (_) { return []; }
  }
  function writeBackup(list) { try { if (io.storage) io.storage.setItem(K.BACKUP, JSON.stringify(list)); } catch (_) { /* 存不下就只靠全局变量 */ } }

  // ── 读 ──
  let lastRestored = 0;
  function readRaw() {
    let vars = null;
    try { vars = io.getGlobal(); } catch (_) { vars = null; }
    if (!plainObj(vars)) return { list: readBackup(), fromBackup: true, missing: true };
    const v = vars[K.KEY];
    if (!plainObj(v) || !Array.isArray(v.列表)) return { list: [], missing: true };
    return { list: v.列表.map(cleanItem).filter(Boolean), missing: false };
  }
  const order = (list) => list.slice().sort((a, b) => (b.自动 ? 1 : 0) - (a.自动 ? 1 : 0) || String(b.时间).localeCompare(String(a.时间)));
  /** 同步读出全部存档（自动那条排最前，其余新的在前） */
  function list() {
    const r = readRaw();
    if (r.missing && !r.fromBackup) {
      const b = readBackup();
      if (b.length) return order(b);
    }
    return order(r.list);
  }
  /** 全局变量里还没有存档、本浏览器有备份时，把备份写回全局变量；返回恢复的条数 */
  async function restoreIfNeeded() {
    const r = readRaw();
    if (!r.missing || r.fromBackup) return 0;
    const b = readBackup();
    if (!b.length) return 0;
    await write(() => b);
    lastRestored = b.length;
    return b.length;
  }

  // ── 写：读最新 → 改 → 写回 → 同步备份 ──
  async function write(fn) {
    let result;
    await io.updateGlobal((vars) => {
      if (!plainObj(vars)) vars = {};
      const v = plainObj(vars[K.KEY]) && Array.isArray(vars[K.KEY].列表) ? vars[K.KEY].列表.map(cleanItem).filter(Boolean) : [];
      const next = fn(v);
      if (next && next.error) { result = next; return vars; }
      const out = Array.isArray(next) ? next : next.list;
      result = Array.isArray(next) ? { ok: true } : next;
      vars[K.KEY] = { 版本: 1, 列表: out };
      return vars;
    });
    if (!result || !result.error) writeBackup(readRaw().list);
    return result && result.error ? { ok: false, ...result } : { ok: true, ...(result || {}) };
  }

  /** 手动保存。同名且没说覆盖 → { ok:false, conflict }；满了 → { ok:false, error } */
  function put(name, draft, opts = {}) {
    const 名 = cleanName(name);
    if (!名) return Promise.resolve({ ok: false, error: '存档名不能是空的' });
    if (名 === K.AUTO) return Promise.resolve({ ok: false, error: `“${K.AUTO}”留给自动存档，换个名字吧` });
    const bad = checkDraft(draft);
    if (bad) return Promise.resolve({ ok: false, error: bad });
    return write((v) => {
      const same = v.find((x) => !x.自动 && !x.来源 && x.名 === 名);
      if (same && !opts.overwrite) return { error: '已经有同名存档', conflict: { id: same.id, 名 } };
      if (!same && v.length >= K.LIMIT) return { error: `存档满了（${K.LIMIT} 份）：先在“读取存档”里删几份` };
      const item = { id: same ? same.id : newId(), 名, 时间: now().toISOString(), 草稿: copy(draft) };
      return { list: same ? v.map((x) => (x === same ? item : x)) : v.concat(item), id: item.id, count: same ? v.length : v.length + 1 };
    });
  }
  /** 落笔成功后自动存“上次开局”；满了且还没有这一条时不存 */
  function auto(draft) {
    if (checkDraft(draft)) return Promise.resolve({ ok: false, error: '草稿不对' });
    return write((v) => {
      const old = v.find((x) => x.自动);
      if (!old && v.length >= K.LIMIT) return { error: `存档满了（${K.LIMIT} 份），这次没自动存“${K.AUTO}”` };
      const item = { id: old ? old.id : newId(), 名: K.AUTO, 时间: now().toISOString(), 草稿: copy(draft), 自动: true };
      return { list: old ? v.map((x) => (x === old ? item : x)) : v.concat(item), id: item.id };
    });
  }
  function rename(id, name) {
    const 名 = cleanName(name);
    if (!名) return Promise.resolve({ ok: false, error: '存档名不能是空的' });
    if (名 === K.AUTO) return Promise.resolve({ ok: false, error: `“${K.AUTO}”留给自动存档，换个名字吧` });
    return write((v) => {
      const it = v.find((x) => x.id === id);
      if (!it) return { error: '这份存档已经不在了' };
      if (it.自动 || it.来源) return { error: '自动存档和工坊存档不能改名' };
      if (v.some((x) => x !== it && !x.自动 && !x.来源 && x.名 === 名)) return { error: '已经有同名存档' };
      return v.map((x) => (x === it ? { ...x, 名 } : x));
    });
  }
  function remove(id) {
    return write((v) => (v.some((x) => x.id === id) ? v.filter((x) => x.id !== id) : { error: '这份存档已经不在了' }));
  }
  const get = (id) => list().find((x) => x.id === id) || null;

  /** 名字撞了就在后面加（2）（3）…… */
  function uniqueName(v, name) {
    const base = cleanName(name) || '未命名';
    const taken = new Set(v.map((x) => x.名));
    if (!taken.has(base) && base !== K.AUTO) return base;
    for (let i = 2; ; i += 1) { const n = cleanName(`${base.slice(0, K.NAME_MAX - 5)}（${i}）`); if (!taken.has(n)) return n; }
  }

  // ── 导出、导入文件 ──
  function exportOf(item) {
    return { 格式: K.FORMAT, 版本: 1, 名: item.名, 时间: item.时间, 草稿: copy(item.草稿) };
  }
  /** 解析导出文件的文字；返回 { ok, item:{名,时间,草稿} } 或 { ok:false, error } */
  function parseFile(text) {
    let o;
    try { o = JSON.parse(String(text).replace(/^﻿/u, '')); } catch (_) { return { ok: false, error: '不是 JSON 文件' }; }
    if (!plainObj(o) || o.格式 !== K.FORMAT) return { ok: false, error: '这不是斗罗开局的存档文件' };
    if (Number(o.版本) > 1) return { ok: false, error: '这份存档来自更新的版本，请先更新卡' };
    const bad = checkDraft(o.草稿);
    if (bad) return { ok: false, error: bad };
    return { ok: true, item: { 名: cleanName(o.名) || '导入的存档', 时间: String(o.时间 || ''), 草稿: copy(o.草稿) } };
  }
  function importFile(text) {
    const p = parseFile(text);
    if (!p.ok) return Promise.resolve(p);
    return write((v) => {
      if (v.length >= K.LIMIT) return { error: `存档满了（${K.LIMIT} 份）：先删几份再导入` };
      const item = { id: newId(), 名: uniqueName(v, p.item.名), 时间: now().toISOString(), 草稿: p.item.草稿 };
      return { list: v.concat(item), id: item.id, 名: item.名 };
    });
  }

  // ── 创意工坊：整批新添、按作品卸载 ──
  /** items = [{ 名, 草稿 }]；全部能放下才写，否则一条都不写 */
  function addFromWork(work, items) {
    const src = { 作品: String(work.id), 作品名: cleanName(work.名 || work.title) || '', 版本: Number(work.版本 || work.version) || 1 };
    for (const it of items) { const bad = checkDraft(it && it.草稿); if (bad) return Promise.resolve({ ok: false, error: `“${cleanName(it && it.名) || '未命名'}”：${bad}` }); }
    return write((v) => {
      const rest = v.filter((x) => !(x.来源 && x.来源.作品 === src.作品));
      if (rest.length + items.length > K.LIMIT) return { error: `存档会超过 ${K.LIMIT} 份（现有 ${rest.length}，要加 ${items.length}）：先在“读取存档”里删几份` };
      const added = [];
      const out = rest.slice();
      for (const it of items) {
        const item = { id: newId() + added.length, 名: uniqueName(out, it.名), 时间: now().toISOString(), 草稿: copy(it.草稿), 来源: src };
        out.push(item); added.push(item.id);
      }
      return { list: out, ids: added };
    });
  }
  function removeByWork(workId) {
    const w = String(workId);
    return write((v) => {
      const out = v.filter((x) => !(x.来源 && x.来源.作品 === w));
      return { list: out, removed: v.length - out.length };
    });
  }

  return { list, get, put, auto, rename, remove, exportOf, parseFile, importFile, addFromWork, removeByWork, restoreIfNeeded, restored: () => lastRestored, checkDraft, cleanName, LIMIT: K.LIMIT, AUTO: K.AUTO };
}

const DL_BOOK = {"repo": "1798547983tt/douluo-card-scripts", "major": 2, "min": "2.1.0", "cdns": ["https://testingcf.jsdelivr.net/gh/", "https://cdn.jsdelivr.net/gh/", "https://fastly.jsdelivr.net/gh/"], "channels": ["https://testingcf.jsdelivr.net/gh/1798547983tt/douluo-card-scripts@main/channels.json", "https://cdn.jsdelivr.net/gh/1798547983tt/douluo-card-scripts@main/channels.json", "https://fastly.jsdelivr.net/gh/1798547983tt/douluo-card-scripts@main/channels.json", "https://raw.githubusercontent.com/1798547983tt/douluo-card-scripts/main/channels.json"], "wait": 4000};
/* 斗罗世界书：远程安装与更新（设计见 变量系统/远程世界书/设计.md）
 * 卡里可以不带世界书（轻量版），开局页或剧情窗口面板从 jsDelivr 下载整本，按酒馆自己“导入卡内世界书”的三步写进去：
 *   convertCharacterBook → saveWorldInfo(名, 数据, true) → updateWorldInfoList（都在 SillyTavern.getContext() 里）。
 * 已经有书时只按规则更新：没动过的原版条目换成新版，玩家或创意工坊改过的不动（planBookUpdate）。
 * 前半是纯函数（tests/世界书测试.cjs 直接载入），后半 bookFlow 是下载与写入，酒馆接口都从参数传进来。
 * build.py 在本段之前注入 DL_BOOK：{ repo, major, min, cdns, channels, wait }（和远程脚本同一个仓库、同一套版本）。
 * 开局（宿主.js）和剧情窗口（剧情窗口.js）各带一份；两边同时写由主窗口上的 __DL_BOOK_BUSY__ 挡住。
 */
const BOOK_NAME = '斗罗宇宙';
const BOOK_STAMP = '斗罗世界书版本';
const BOOK_BUSY = '__DL_BOOK_BUSY__';

/** 53 位内容哈希（cyrb53，逐个 UTF-16 码元），14 位十六进制。
 * 不用 SHA-256：酒馆用局域网 http 打开时没有 crypto.subtle。Python 侧 远程/远程.py 的 h53 是同一份算法（测试里对过）。 */
function h53(str) {
  const s = String(str);
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < s.length; i += 1) {
    const ch = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0');
}

const bookEntries = (data) => (data && data.entries && typeof data.entries === 'object' ? data.entries : {});
const byUid = (entries) => Object.values(entries).filter((e) => e && typeof e === 'object').sort((a, b) => Number(a.uid) - Number(b.uid));

/** 书里的版本戳（酒馆格式的整本数据）：{ 书版本, 标签, 条数 }；没有或坏了就是 null */
function stampOf(data) {
  const e = byUid(bookEntries(data)).find((x) => x.comment === BOOK_STAMP);
  if (!e) return null;
  try {
    const v = JSON.parse(String(e.content || ''));
    return v && typeof v.书版本 === 'string' && v.书版本 ? v : null;
  } catch (_) {
    return null;
  }
}

const mb = (bytes) => (Number(bytes) > 0 ? Math.max(0.1, Math.round(Number(bytes) / 1048576 * 10) / 10) : null);

/** 书的状态：没装 / 最新 / 有新版 / 查不到。
 * has：主世界书名字在、文件也在（酒馆助手只看卡上写的名字，不管文件在不在）；manifest：仓库里的清单，没拿到是 null。 */
function bookState({ has, data, manifest, error }) {
  const stamp = has ? stampOf(data) : null;
  const size = manifest ? mb(manifest.传输字节 || manifest.字节) : null;
  if (!has) {
    return manifest
      ? { 状态: '没装', 可开局: false, 文字: `世界书还没装${size ? `（下载约 ${size} MB）` : ''}：装好才能开局。`, 动作: '下载并安装' }
      : { 状态: '没装', 可开局: false, 文字: `世界书还没装，也连不上下载地址${error ? `（${error}）` : ''}。检查网络后重试，或者改用完整版卡。`, 动作: '重试' };
  }
  const label = stamp ? stamp.标签 || stamp.书版本 : '版本未知';
  if (!manifest) return { 状态: '查不到', 可开局: true, 文字: `世界书 ${label}：查不到有没有新版${error ? `（${error}）` : ''}，不影响开局。`, 动作: null, 戳: stamp };
  if (stamp && stamp.书版本 === manifest.书版本) return { 状态: '最新', 可开局: true, 文字: `世界书 ${label}，已是最新。`, 动作: null, 戳: stamp };
  return {
    状态: '有新版', 可开局: true, 戳: stamp, 动作: '更新',
    文字: stamp ? `世界书有新版 ${manifest.标签}（现在是 ${label}）：更新会保留你改过的条目。` : `世界书有新版 ${manifest.标签}（现在这本没有版本戳，是从老卡导进来的）：更新会保留认不出来的条目。`,
  };
}

/** 已有的书按新版更新（都是酒馆格式的 entries：uid → 条目）。
 * known：{ 条目名: [原版正文 h53, …] }，历次正式版本里出现过的正文；force：要强行用新版覆盖的条目名。
 * 规则（设计 §3.4）：按条目名配对，同名多条按 uid 先后配；
 *   没动过（正文在 known 里）或在 force 里 → 换成新版整条，保留 uid、开关（disable）和显示顺序；改过 → 不动，记进“保留”；
 *   新版多出来的 → 新增，uid 接在最后；新版没有了、而且没动过的原版 → 删；玩家和工坊自己加的 → 不动；版本戳总是换新。 */
function planBookUpdate(cur, next, known, force) {
  const K = known && typeof known === 'object' ? known : {};
  const F = new Set(force || []);
  const isOrig = (e) => Array.isArray(K[e.comment]) && K[e.comment].includes(h53(e.content == null ? '' : e.content));
  const curList = byUid(cur || {});
  const pool = new Map();
  for (const e of curList) {
    const k = String(e.comment == null ? '' : e.comment);
    if (!pool.has(k)) pool.set(k, []);
    pool.get(k).push(e);
  }
  const out = {};
  const used = new Set();
  const 报告 = { 更新: 0, 新增: 0, 删除: 0, 不变: 0, 保留: [] };
  let nextUid = curList.reduce((m, e) => Math.max(m, Number(e.uid) + 1), 0);
  const same = (a, b) => {
    const strip = ({ uid, disable, displayIndex, ...rest }) => rest; // eslint-disable-line no-unused-vars
    return JSON.stringify(strip(a)) === JSON.stringify(strip(b));
  };
  for (const n of byUid(next || {})) {
    const k = String(n.comment == null ? '' : n.comment);
    const c = (pool.get(k) || []).find((x) => !used.has(x));
    if (c) used.add(c);
    if (!c) {
      const uid = nextUid;
      nextUid += 1;
      out[uid] = { ...n, uid, displayIndex: uid };
      报告.新增 += 1;
    } else if (k === BOOK_STAMP || isOrig(c) || F.has(k)) {
      const e = { ...n, uid: c.uid, displayIndex: c.displayIndex == null ? n.displayIndex : c.displayIndex };
      if (k !== BOOK_STAMP) e.disable = c.disable;
      out[c.uid] = e;
      if (same(c, e)) 报告.不变 += 1;
      else 报告.更新 += 1;
    } else {
      out[c.uid] = c;
      报告.保留.push(k);
    }
  }
  const nextNames = new Set(byUid(next || {}).map((n) => String(n.comment == null ? '' : n.comment)));
  for (const c of curList) {
    if (used.has(c)) continue;
    if (!nextNames.has(String(c.comment)) && isOrig(c)) 报告.删除 += 1;
    else out[c.uid] = c;
  }
  return { entries: out, 报告 };
}

/** 清单：{ 名, 书版本, 标签, 条数, 字节, 传输字节?, 分片: [{ 文件, 条数, 字节, h53 }], 已知原版 } */
function checkManifest(m) {
  const bad = (why) => { throw new Error('世界书清单不对：' + why); };
  if (!m || typeof m !== 'object') bad('不是对象');
  if (typeof m.书版本 !== 'string' || !/^[0-9a-f]{12}$/.test(m.书版本)) bad('书版本');
  if (!Array.isArray(m.分片) || !m.分片.length) bad('分片');
  let n = 0;
  for (const p of m.分片) {
    if (!p || typeof p.文件 !== 'string' || !/^part-\d{2}\.json$/.test(p.文件)) bad('分片文件名');
    if (typeof p.h53 !== 'string' || !/^[0-9a-f]{14}$/.test(p.h53)) bad('分片哈希');
    if (!Number.isInteger(p.条数) || p.条数 <= 0) bad('分片条数');
    n += p.条数;
  }
  if (n !== m.条数) bad('条数合计');
  if (!m.已知原版 || typeof m.已知原版 !== 'object') bad('已知原版');
  return m;
}

/** 一个分片：哈希、条数、每条的字段都要对（镜像返回错误页、下到一半断了、拿错文件都会在这里被挡下） */
function checkPart(text, meta) {
  if (h53(text) !== meta.h53) throw new Error(`${meta.文件} 内容不完整或不是这一版`);
  let list;
  try { list = JSON.parse(text); } catch (_) { throw new Error(`${meta.文件} 不是 JSON`); }
  if (!Array.isArray(list) || list.length !== meta.条数) throw new Error(`${meta.文件} 条数不对`);
  for (const e of list) {
    if (!e || !Number.isInteger(e.id) || typeof e.comment !== 'string' || typeof e.content !== 'string' || !Array.isArray(e.keys)) {
      throw new Error(`${meta.文件} 里有条目格式不对`);
    }
  }
  return list;
}

/** 下载与写入。deps：{ W 主窗口, cfg: DL_BOOK, ctx() 酒馆上下文, api(name) 酒馆助手函数, generating() 正在生成？ } */
function bookFlow(deps) {
  const { W, cfg } = deps;
  const HEAD_WAIT = (cfg && cfg.headWait) || 15000;
  let memoManifest = null; // { ver, promise }
  let memoEntries = null; // { 书版本, list }

  async function version() {
    try {
      const R = W.__DL_REMOTE_V1__;
      if (R && typeof R.version === 'function') return await R.version(cfg);
    } catch (_) { /* 解析器出错就用保底版本 */ }
    return cfg.min;
  }
  /** 按镜像顺序取一个文件，check 不过（错误页、断了、旧缓存）就换下一个镜像；只等响应头，正文下载不设上限 */
  async function getChecked(path, ver, check) {
    const errors = [];
    for (const cdn of cfg.cdns) {
      const url = cdn + cfg.repo + '@' + ver + '/dist/book/' + path;
      const ac = new W.AbortController();
      const t = W.setTimeout(() => ac.abort(), HEAD_WAIT);
      try {
        const r = await W.fetch(url, { signal: ac.signal });
        W.clearTimeout(t);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return check(await r.text());
      } catch (e) {
        W.clearTimeout(t);
        errors.push(cdn.replace(/^https:\/\/|\/gh\/$/g, '') + ' ' + (e && e.name === 'AbortError' ? '超时' : (e && e.message) || e));
      }
    }
    throw new Error(errors.join('；'));
  }
  async function manifest() {
    const ver = await version();
    if (memoManifest && memoManifest.ver === ver) return memoManifest.promise;
    const promise = getChecked('manifest.json', ver, (t) => checkManifest(JSON.parse(t)));
    memoManifest = { ver, promise };
    promise.catch(() => { if (memoManifest && memoManifest.promise === promise) memoManifest = null; });
    return promise;
  }
  async function download(m, progress) {
    if (memoEntries && memoEntries.书版本 === m.书版本) return memoEntries.list;
    const ver = await version();
    const list = [];
    for (let i = 0; i < m.分片.length; i += 1) {
      const p = m.分片[i];
      progress({ 步: '下载', i, n: m.分片.length });
      let part = null, lastErr = null;
      for (let k = 0; k < 2 && !part; k += 1) { // 三个镜像都不行就整轮再试一次
        try { part = await getChecked(p.文件, ver, (t) => checkPart(t, p)); } catch (e) { lastErr = e; }
      }
      if (!part) throw lastErr || new Error('下载失败');
      for (const e of part) list.push(e);
    }
    if (list.length !== m.条数) throw new Error('世界书条数不对');
    memoEntries = { 书版本: m.书版本, list };
    return list;
  }
  const th = (name) => { const f = deps.api(name); if (!f) throw new Error(`酒馆助手里找不到 ${name}：请更新酒馆助手。`); return f; };
  const st = () => {
    const c = deps.ctx();
    for (const f of ['convertCharacterBook', 'saveWorldInfo', 'loadWorldInfo', 'updateWorldInfoList']) {
      if (!c || typeof c[f] !== 'function') throw new Error(`这个酒馆版本不支持脚本安装世界书（缺 ${f}）：请改用完整版卡，或更新酒馆。`);
    }
    return c;
  };
  function where() {
    const names = th('getWorldbookNames')() || [];
    const cb = th('getCharWorldbookNames')('current') || {};
    const primary = cb.primary || null;
    return { names, primary, additional: Array.isArray(cb.additional) ? cb.additional : [], target: primary || BOOK_NAME, has: !!(primary && names.includes(primary)) };
  }
  async function status() {
    const w = where();
    const data = w.has ? await st().loadWorldInfo(w.target) : null;
    let m = null, error = '';
    try { m = await manifest(); } catch (e) { error = (e && e.message) || String(e); }
    return { ...bookState({ has: w.has, data, manifest: m, error }), 书名: w.target, 清单: m };
  }
  async function write(fn) {
    if (deps.generating && deps.generating()) throw new Error('AI 正在生成，等它停下再装世界书。');
    if (W[BOOK_BUSY]) throw new Error('世界书正在写入，稍等再试。');
    W[BOOK_BUSY] = true;
    try { return await fn(); } finally { W[BOOK_BUSY] = false; }
  }
  /** 没书时装整本；有书时更新。force：要强行用新版覆盖的条目名（更新报告里“保留”的那些） */
  async function apply(progress = () => {}, force = null) {
    const c = st();
    const m = await manifest();
    const list = await download(m, progress);
    progress({ 步: '写入' });
    return write(async () => {
      const w = where();
      const next = c.convertCharacterBook({ name: w.target, entries: JSON.parse(JSON.stringify(list)) });
      delete next.originalData; // 酒馆只在编辑器同步关键词时可选地用它，留着世界书文件就多存一份原文
      let 报告;
      if (!w.has) {
        await c.saveWorldInfo(w.target, next, true);
        报告 = { 安装: Object.keys(next.entries).length };
      } else {
        const cur = JSON.parse(JSON.stringify((await c.loadWorldInfo(w.target)) || {}));
        const plan = planBookUpdate(bookEntries(cur), next.entries, m.已知原版, force);
        delete cur.originalData;
        await c.saveWorldInfo(w.target, { ...cur, entries: plan.entries }, true);
        报告 = plan.报告;
      }
      await c.updateWorldInfoList();
      if (!w.primary) await th('rebindCharWorldbooks')('current', { primary: w.target, additional: w.additional });
      return { 书名: w.target, 标签: m.标签, ...报告 };
    });
  }
  return { status, apply, manifest, version };
}

/** 报告写成一句话 */
function bookReportText(r) {
  if (!r) return '';
  if (r.安装) return `世界书 ${r.标签 || ''} 装好了：${r.安装} 条。`;
  const bits = [`更新 ${r.更新} 条`, r.新增 ? `新增 ${r.新增} 条` : '', r.删除 ? `删掉原版已去掉的 ${r.删除} 条` : '', r.保留.length ? `保留你改过的 ${r.保留.length} 条` : ''].filter(Boolean);
  return `世界书已更新到 ${r.标签 || '新版'}：${bits.join('，')}。`;
}

/* 斗罗开局 · 酒馆宿主适配（酒馆助手脚本）
 * build.py 在本段之前注入：
 *   OPEN_CSS   样稿 <style id="dlo-style"> 的全文
 *   OPEN_CODE  共用/规则.js ＋ 幕索引 ＋ 开局/窗口.js ＋ 开局/建档.js ＋ 样稿“开局本体”，末尾把规则函数挂到 DLOpening.lib
 *   DL_WINDOW_SCRIPT_ID  斗罗剧情窗口脚本的 id（读它的脚本变量：自动开关、后几幕数量）
 *   createSaveStore  开局/存档.js（存档存在酒馆全局变量，本浏览器留备份）
 * 这里只做接线（设计决定 §16.3、§16.5）：
 *   - 开场白里有 <开局创建角色> 时，把 0 楼换成封面菜单；开过局以后换成只读的开局档案卡
 *   - 建档层要的数据：幕索引、世界书条目、头像、草稿、存档
 *   - 落笔：写 0 楼变量 → 读回核对 → 打开剧情窗口 → 写开局记录 → 发出开局消息；发出前任何一步失败都按相反顺序撤回；
 *     写完以后自动存一份“上次开局”（存不上只提示，不影响开局）
 *   - 脚本按钮“重新开局”：只剩 0 楼时把 0 楼变量还原成开局前的样子，再打开建档层
 *   - 创意工坊：斗罗创意工坊脚本在主页面挂 DLWorkshop；没启用时菜单点了只提示
 *   - 世界书（开局/世界书.js，build.py 在本段之前注入 DL_BOOK 和它）：封面显示状态，没装时下载安装、有新版时按规则更新；没装不让落笔
 * 外观全在本体里，不在这里改。
 */
(function () {
  'use strict';
  const NAME = '斗罗开局';
  const GLOBAL = '__DL_OPENING__';
  const TOKEN = '<开局创建角色>';
  const STATE_KEY = '斗罗开局';
  const DRAFT_PREFIX = 'dl-opening-draft:';
  const MSG_TAG = '<开局档案>';
  const RESTART = '重新开局';
  const W = (() => { try { if (window.parent && window.parent !== window && window.parent.document) return window.parent; } catch (_) { /* 跨域时退回本窗口 */ } return window; })();
  const D = W.document;
  const sleep = (ms) => new Promise((r) => W.setTimeout(r, ms));
  const clone = (o) => (o == null ? o : JSON.parse(JSON.stringify(o)));
  const log = (...a) => console.info(`[${NAME}]`, ...a);

  // ───────── 酒馆助手接口：先用脚本自己窗口上的，没有再找主页面的 TavernHelper ─────────
  const api = (name) => {
    if (typeof window[name] === 'function') return window[name].bind(window);
    try { const f = W.TavernHelper && W.TavernHelper[name]; if (typeof f === 'function') return f.bind(W.TavernHelper); } catch (_) { /* 读不到 */ }
    return null;
  };
  const need = (name) => { const f = api(name); if (!f) throw new Error(`酒馆助手里找不到 ${name}：请确认酒馆助手已启用并更新到 4.8 以上。`); return f; };
  const ctx = () => { try { return W.SillyTavern && W.SillyTavern.getContext ? W.SillyTavern.getContext() : null; } catch (_) { return null; } };
  const chat = () => { const c = ctx(); return c && Array.isArray(c.chat) ? c.chat : []; };
  const chatId = () => { const c = ctx(); try { return String((c && (c.getCurrentChatId ? c.getCurrentChatId() : c.chatId)) || ''); } catch (_) { return ''; } };
  const mvu = () => window.Mvu || W.Mvu || null;
  const EVENTS = {
    CHAT_CHANGED: 'chat_id_changed', MESSAGE_SENT: 'message_sent', MESSAGE_RECEIVED: 'message_received', MESSAGE_SWIPED: 'message_swiped',
    MESSAGE_EDITED: 'message_edited', MESSAGE_UPDATED: 'message_updated', MESSAGE_DELETED: 'message_deleted',
    CHARACTER_MESSAGE_RENDERED: 'character_message_rendered', USER_MESSAGE_RENDERED: 'user_message_rendered',
    MORE_MESSAGES_LOADED: 'more_messages_loaded', GENERATION_ENDED: 'generation_ended', CHAT_CREATED: 'chat_created',
  };
  const stops = [];
  function on(key, fn) {
    const eventOn = api('eventOn');
    if (!eventOn) return;
    const names = window.tavern_events || W.tavern_events || {};
    try {
      const r = eventOn(names[key] || EVENTS[key], fn);
      stops.push(typeof r === 'function' ? r : r && typeof r.stop === 'function' ? () => r.stop() : () => {});
    } catch (_) { /* 这个事件名在当前版本里没有 */ }
  }
  function notify(text, level = 'info') {
    (level === 'error' ? console.error : level === 'warning' ? console.warn : console.info)(`[${NAME}]`, text);
    try { W.toastr && W.toastr[level] && W.toastr[level](text, NAME, { timeOut: level === 'error' ? 12000 : 5000 }); } catch (_) { /* 没有 toastr */ }
  }

  // ───────── 本体：放进酒馆主页面运行（WebGL 动画不受隐藏 iframe 节流） ─────────
  function loadPage() {
    let style = D.getElementById('dlo-style');
    if (!style) { style = D.createElement('style'); style.id = 'dlo-style'; D.head.append(style); }
    style.textContent = OPEN_CSS;
    try { if (W.DLOpening && W.DLOpening.close) W.DLOpening.close(); } catch (_) { /* 旧本体已失效 */ }
    new W.Function(OPEN_CODE)();
    return W.DLOpening;
  }

  // ───────── 存取 ─────────
  function readRecord() {
    try { const v = need('getVariables')({ type: 'chat' }); const r = v && v[STATE_KEY]; return r && typeof r === 'object' && r.部 ? r : null; } catch (_) { return null; }
  }
  async function writeRecord(value) {
    await need('updateVariablesWith')((vars) => {
      if (value == null) delete vars[STATE_KEY];
      else vars[STATE_KEY] = value;
      return vars;
    }, { type: 'chat' });
  }
  let storage = null;
  try { storage = W.localStorage; } catch (_) { storage = null; }
  const drafts = {
    get(id) { try { const t = storage && storage.getItem(DRAFT_PREFIX + id); return t ? JSON.parse(t) : null; } catch (_) { return null; } },
    set(id, d) { try { if (storage && id) storage.setItem(DRAFT_PREFIX + id, JSON.stringify(d)); } catch (_) { /* 存不下就算了 */ } },
    remove(id) { try { if (storage) storage.removeItem(DRAFT_PREFIX + id); } catch (_) { /* 无所谓 */ } },
  };
  const saves = createSaveStore({
    getGlobal: () => need('getVariables')({ type: 'global' }),
    updateGlobal: (fn) => need('updateVariablesWith')(fn, { type: 'global' }),
    storage,
  });
  function workshop(opts) {
    try { if (W.DLWorkshop && typeof W.DLWorkshop.open === 'function') { W.DLWorkshop.open(opts || {}); return true; } } catch (e) { console.warn(`[${NAME}] 打不开创意工坊`, e); }
    return false;
  }
  function windowSettings() {
    let v = null;
    try { v = need('getVariables')({ type: 'script', script_id: DL_WINDOW_SCRIPT_ID }); } catch (_) { v = null; }
    const o = v && typeof v === 'object' ? v : {};
    const auto = o['自动剧情窗口'];
    const n = Math.round(Number(o['剧情窗口后几幕']));
    return {
      auto: !(auto === false || auto === 0 || /^(false|0|off|no|关|否|不)$/iu.test(String(auto == null ? '' : auto).trim())),
      n: Number.isFinite(n) && o['剧情窗口后几幕'] !== '' && o['剧情窗口后几幕'] != null ? Math.min(4, Math.max(0, n)) : 4,
    };
  }
  // 主世界书：卡上写着名字、而且这本书真的在（酒馆助手只看卡上的名字；轻量版卡在装世界书之前文件不在）
  const primaryBook = () => {
    try {
      const r = api('getCharWorldbookNames') && api('getCharWorldbookNames')('current');
      const p = (r && r.primary) || null;
      const names = api('getWorldbookNames') ? api('getWorldbookNames')() : null;
      return p && (!Array.isArray(names) || names.includes(p)) ? p : null;
    } catch (_) { return null; }
  };
  const extraBooks = () => {
    try {
      const r = api('getCharWorldbookNames') && api('getCharWorldbookNames')('current');
      const pri = (r && r.primary) || '';
      const add = r && Array.isArray(r.additional) ? r.additional : [];
      return [...new Set(add.map((x) => String(x || '').trim()).filter((x) => x && x !== pri))];
    } catch (_) { return []; }
  };
  async function waitMvu(timeout = 6000) {
    if (mvu()) return mvu();
    const wait = api('waitGlobalInitialized');
    if (wait) { try { await Promise.race([wait('Mvu'), sleep(timeout)]); } catch (_) { /* 等不到就当没有 */ } }
    return mvu();
  }
  const readMvu = (id) => { try { const d = mvu().getMvuData({ type: 'message', message_id: id }); return d && typeof d === 'object' ? d : null; } catch (_) { return null; } };
  const sendField = () => { const t = D.getElementById('send_textarea'), b = D.getElementById('send_but'); return t && b ? { t, b } : null; };
  const isGenerating = () => D.body && D.body.dataset && D.body.dataset.generating === 'true';
  // ───────── 世界书：没装就装，有新版就更新 ─────────
  const books = bookFlow({ W, cfg: DL_BOOK, ctx, api, generating: isGenerating });
  async function bookStatus() {
    try { return await books.status(); } catch (e) { return { 状态: '出错', 可开局: !!primaryBook(), 文字: `世界书状态读不出来：${(e && e.message) || e}`, 动作: null }; }
  }
  async function bookApply(say, force) {
    const r = await books.apply((x) => { if (say) say(x.步 === '下载' ? `正在下载世界书（${x.i + 1}/${x.n}）…` : '正在写入世界书…'); }, force);
    log(bookReportText(r), r.保留 && r.保留.length ? r.保留 : '');
    return { ...r, 文字: bookReportText(r) };
  }
  const isOnline = () => { const c = ctx(); return !c || c.onlineStatus === undefined || c.onlineStatus !== 'no_connection'; };
  function motion() {
    const m = D.documentElement.dataset.dlMotion;
    if (m && m !== 'full') return 'off';
    try { if (W.matchMedia('(prefers-reduced-motion: reduce)').matches) return 'off'; } catch (_) { /* 老浏览器 */ }
    return 'on';
  }

  // ───────── 落笔事务 ─────────
  const isOpeningMessage = (m, act) => !!(m && m.is_user && typeof m.mes === 'string' && m.mes.includes(MSG_TAG) && (!act || m.mes.includes(act)));
  async function sendAndConfirm(text, act, timeout = 15000) {
    const f = sendField();
    if (!f) return -1;
    f.t.value = text;
    f.t.dispatchEvent(new W.Event('input', { bubbles: true }));
    const from = chat().length;
    f.b.click();
    const end = Date.now() + timeout;
    while (Date.now() < end) {
      const c = chat();
      for (let i = c.length - 1; i >= from; i -= 1) if (isOpeningMessage(c[i], act)) return i;
      await sleep(200);
    }
    return -1;
  }
  function summaryOf(L, d, p) {
    const name = d.类型 === '原作角色' ? d.原作身份 : d.姓名;
    const soul = d.武魂 && d.武魂[0];
    const body = d.类型 === '原作角色' ? ''
      : L.isBeastBody(d) ? ` · ${d.魂兽.种族 || '魂兽'}（兽身）`
        : L.isDeity(d) ? ` · ${d.神祇.神阶}${d.神祇.神名 ? '「' + d.神祇.神名 + '」' : ''}`
          : soul && soul.名称 ? ` · ${soul.名称}（${soul.品质}）· ${d.魂力等级} 级 · ${soul.魂环.length} 环` : '';
    return {
      部: d.部, 姓名: name, 日期: L.fmtDate(p.事件[1]), 幕: p.幕.名, 事件: `事件${p.事件[0]} ${p.事件[3]}`,
      叙事核心: L.isCore(d.叙事核心) ? d.叙事核心 : L.NO_CORE,
      金手指: L.isGf(d.金手指) ? d.金手指 : L.NO_GF,
      气运: Array.isArray(d.气运) ? d.气运.slice() : [],
      摘要: `${d.类型} · ${d.来历}${body}`,
      环: d.类型 !== '原作角色' && !L.isBeastBody(d) && !L.isDeity(d) && soul ? soul.魂环.map((r) => r.年限) : [],
    };
  }
  async function commit(id, payload, progress) {
    const page = W.DLOpening, L = page.lib, index = page.index;
    const guard = () => { if (chatId() !== id) throw new Error('聊天已经切换，这次开局取消了。'); };
    const c = chat();
    if (!c.length) throw new Error('这段聊天还没有开场白。');
    if (c.length > 1) throw new Error('开场白后面已经有楼层了：开局只能在只剩开场白时进行。请开新聊天，或删掉开场白之后的楼层再试。');
    if (isGenerating()) throw new Error('AI 正在生成，等它停下再落笔。');
    if (!isOnline()) throw new Error('还没连上 AI 接口：先在 API 设置里连上，再落笔。');
    if (!sendField()) throw new Error('找不到酒馆的输入框和发送按钮。');
    if (sendField().t.value.trim()) throw new Error('输入框里还有没发出的字：先清空或另存，再落笔（开局消息要从输入框发出）。');
    const book = primaryBook();
    if (!book) throw new Error('世界书还没装：回到封面点“下载并安装”（用完整版卡的，导入卡时选择导入内嵌世界书），再落笔。');
    progress('正在读取变量…');
    if (!(await waitMvu())) throw new Error('没有找到 MVU：请先启用 MVU 和斗罗ZOD 两个脚本，刷新页面后再试。');
    for (const f of ['parseMessage', 'replaceMvuData', 'getMvuData']) if (typeof mvu()[f] !== 'function') throw new Error(`MVU 没有提供 ${f}：请把 MVU 更新到最新版。`);
    guard();
    const current = readMvu(0);
    if (!current || !current.stat_data || !Object.keys(current.stat_data).length) throw new Error('开场白这一楼还没有初始变量：请确认 MVU 已启用、世界书里有 [initvar] 条目，刷新页面后再试。');
    const prev = readRecord();
    // 开过局又删了楼层：从那次开局前的变量重新套，免得叠两遍
    const pristine = prev && prev.提交前变量 && prev.提交前变量.stat_data ? prev.提交前变量 : current;
    const before = clone(current);
    const undo = [];
    const rollback = async () => {
      for (const step of undo.splice(0).reverse()) { try { await step(); } catch (e) { console.warn(`[${NAME}] 撤回时出错`, e); } }
    };
    const d = payload.draft;
    const p = L.pointOf(index, d);
    let record;
    try {
      progress('正在写入变量…');
      const text = `<UpdateVariable>\n<JSONPatch>\n${JSON.stringify(payload.patch)}\n</JSONPatch>\n</UpdateVariable>`;
      const next = await mvu().parseMessage(text, clone(pristine));
      if (!next || !next.stat_data) throw new Error('MVU 没能处理开局变量。');
      guard();
      await mvu().replaceMvuData(next, { type: 'message', message_id: 0 });
      undo.push(() => (chatId() === id ? mvu().replaceMvuData(before, { type: 'message', message_id: 0 }) : undefined));
      const rb = (readMvu(0) || {}).stat_data || {};
      const want = Object.fromEntries(payload.patch.map((op) => [op.path, op.value]));
      const bad = [];
      if (!rb.时空 || rb.时空.外界日期 !== want['/时空/外界日期']) bad.push('外界日期');
      if (!rb.主角 || rb.主角.姓名 !== want['/主角'].姓名) bad.push('主角姓名');
      if (!rb.原作指导 || rb.原作指导.当前事件 !== want['/原作指导'].当前事件) bad.push('当前事件');
      if (L.isCore(d.叙事核心) && (!rb.叙事核心 || rb.叙事核心.核心 !== d.叙事核心)) {
        const coreHintName = L.CORES.includes(d.叙事核心) ? `脚本“斗罗核心·${d.叙事核心}”` : `创意工坊叙事核心「${d.叙事核心}」及其脚本与斗罗ZOD`;
        bad.push(`叙事核心（请确认${coreHintName}已启用，刷新页面后再试）`);
      }
      if (L.isGf(d.金手指) && (!rb.金手指 || rb.金手指.类型 !== d.金手指)) {
        const gfHintName = L.GFS.includes(d.金手指) ? `脚本“斗罗金手指·${d.金手指}”` : `创意工坊金手指「${d.金手指}」及其脚本与斗罗ZOD`;
        bad.push(`金手指（请确认${gfHintName}已启用，刷新页面后再试）`);
      }
      // 气运写在主角里：旧版斗罗ZOD 不认这一支，会把它整块丢掉
      const luckWant = Object.keys(((want['/主角'] || {}).气运 || {}).词条 || {}).sort();
      const luckGot = Object.keys(((rb.主角 || {}).气运 || {}).词条 || {}).sort();
      if (luckWant.join('|') !== luckGot.join('|')) bad.push('气运词条（请把斗罗ZOD 更新到带气运的版本，刷新页面后再试）');
      // 宗门、血脉同理：旧版斗罗ZOD 没有这两支
      const sectWant = want['/宗门'];
      if (sectWant && sectWant.名称 && !(rb.宗门 && rb.宗门.名称 === sectWant.名称)) bad.push('宗门（请把斗罗ZOD 更新到带宗门血脉的版本，刷新页面后再试）');
      const bloodWant = Object.keys((want['/主角'] || {}).血脉 || {}).sort();
      const bloodGot = Object.keys((rb.主角 || {}).血脉 || {}).sort();
      if (bloodWant.join('|') !== bloodGot.join('|')) bad.push('血脉（请把斗罗ZOD 更新到带宗门血脉的版本，刷新页面后再试）');
      if (bad.length) throw new Error(`变量写入后核对不上：${bad.join('、')}。`);
      guard();

      // 剧情窗口（那边关了自动就不碰幕条目）＋ 人物条目（始终只开开局所在部）：按写好的变量算，与剧情窗口脚本同一套规则
      const ws = windowSettings();
      const os = L.openingStat(index, d).时空, rt = rb.时空 || {};
      const stat = { 时空: { 外界日期: rt.外界日期 || os.外界日期, 当前部: rt.当前部 || os.当前部, 当前幕: rt.当前幕 || os.当前幕, 地点: rt.地点 || os.地点 || '' } };
      const plan = L.planWindow(index, stat, '', ws.n);
      const entries = await need('getWorldbook')(book);
      const changes = [];
      const part = L.personPart(stat, plan);
      if (part) { progress('正在打开本部人物条目…'); changes.push(...L.personPlan(entries, part).改动); }
      // 世界观条目：通用＋本部，所在地命中的地区条目改蓝灯（和剧情窗口脚本同一条规则）
      if (part) changes.push(...L.worldPlan(entries, part, stat.时空.地点).改动);
      // 叙事核心与金手指条目：只开选中那几条（未选时全关），和剧情窗口脚本同一条规则
      changes.push(...L.corePlan(entries, L.isCore(d.叙事核心) ? d.叙事核心 : null).改动);
      changes.push(...L.gfPlan(entries, L.isGf(d.金手指) ? d.金手指 : null).改动);
      // 宗门速查：读回的变量里有宗门才开（和剧情窗口脚本同一条规则）
      changes.push(...L.sectPlan(entries, rb).改动);
      if (ws.auto && plan) {
        progress('正在打开剧情窗口…');
        const wp = L.windowPlan(index, entries, plan);
        changes.push(...wp.改动);
        if (wp.缺幕.length) notify(`世界书里缺这些幕条目：${wp.缺幕.join('、')}。开局照常，AI 读不到它们的全文。`, 'warning');
      }
      if (changes.length) {
        const back = L.undoEntryChanges(entries, changes);
        await need('updateWorldbookWith')(book, (list) => L.applyEntryChanges(list, changes), { render: 'debounced' });
        undo.push(() => need('updateWorldbookWith')(book, (list) => L.applyEntryChanges(list, back), { render: 'debounced' }));
      }
      // 附加世界书兼容兜底：若玩家手动绑定了含核心/金手指条目的附加世界书，同步开关其条目
      const wantCore = L.isCore(d.叙事核心) ? d.叙事核心 : null;
      const wantGf = L.isGf(d.金手指) ? d.金手指 : null;
      for (const eb of extraBooks()) {
        let eList = null;
        try { eList = await need('getWorldbook')(eb); } catch (_) { eList = null; }
        if (!Array.isArray(eList) || !eList.length) continue;
        const eChanges = [...L.corePlan(eList, wantCore).改动, ...L.gfPlan(eList, wantGf).改动];
        if (!eChanges.length) continue;
        const eSet = new Map(eChanges.map((x) => [x.uid, x.enabled]));
        const applyExtra = (list, invert) => list.map((e) => (eSet.has(e.uid) ? { ...e, enabled: invert ? !eSet.get(e.uid) : eSet.get(e.uid) } : e));
        await need('updateWorldbookWith')(eb, (list) => applyExtra(list, false), { render: 'debounced' });
        undo.push(() => need('updateWorldbookWith')(eb, (list) => applyExtra(list, true), { render: 'debounced' }));
      }
      guard();

      progress('正在写开局记录…');
      record = {
        版本: 1, ...summaryOf(L, d, p), 时间: new Date().toISOString(), 已发送: false,
        草稿: clone(d), 提交前变量: clone(pristine),
      };
      await writeRecord(record);
      undo.push(() => writeRecord(prev || null));
      guard();
    } catch (e) {
      await rollback();
      throw new Error(`${String((e && e.message) || e).replace(/[。.]?$/u, "")}。写进去的内容已经撤回。`);
    }
    drafts.remove(id);
    progress('正在发出开局消息…');
    const sent = await sendAndConfirm(payload.message, p.幕.名);
    let saved = '';
    try {
      const r = await saves.auto(clone(d));
      saved = r.ok ? `已自动存为“${saves.AUTO}”：下次新开聊天，在封面“读取存档”里直接读取。` : r.error;
    } catch (e) { saved = `没能自动存“${saves.AUTO}”：${(e && e.message) || e}`; }
    if (sent < 0) {
      pending = { id };
      return { ok: true, saved, note: '变量和剧情窗口已经写好，但开局消息没能自动发出：它还在输入框里，检查后手动点发送即可。' };
    }
    await markSent(id);
    return { ok: true, saved };
  }
  let pending = null;
  async function markSent(id) {
    pending = null;
    const r = readRecord();
    if (r && !r.已发送 && chatId() === id) { r.已发送 = true; try { await writeRecord(r); } catch (e) { console.warn(`[${NAME}] 开局记录没存上`, e); } }
  }
  // 自动发送没成功、玩家手动发出以后：认出那条开局消息
  function adoptManualSend() {
    if (!pending || pending.id !== chatId()) return;
    if (chat().slice(1).some((m) => isOpeningMessage(m))) markSent(pending.id).then(schedule, () => {});
  }

  // ───────── 给本体的 host ─────────
  function hostFor(id) {
    const avatars = {
      get names() { try { return (W.DLAvatars && W.DLAvatars.people) || []; } catch (_) { return []; } },
      url(n) { try { const v = W.DLAvatars && W.DLAvatars.pick(n, {}); return (v && v.src) || null; } catch (_) { return null; } },
    };
    return {
      doc: D,
      index: W.DLOpening.index,
      avatars,
      async book() {
        const b = primaryBook();
        if (!b) throw new Error('这张卡没有绑定世界书');
        const main = (await need('getWorldbook')(b)).map((e) => ({ uid: e.uid, name: e.name, enabled: e.enabled, content: e.content }));
        const seen = new Set(main.map((e) => e.name));
        for (const eb of extraBooks()) {
          try {
            const sub = await need('getWorldbook')(eb);
            for (const e of sub || []) {
              if (e && e.name && !seen.has(e.name)) {
                seen.add(e.name);
                main.push({ uid: e.uid, name: e.name, enabled: e.enabled, content: e.content, book: eb });
              }
            }
          } catch (_) { /* ignore */ }
        }
        return main;
      },
      loadDraft() { const r = readRecord(); return drafts.get(id) || (r && r.草稿) || null; },
      saveDraft(d) { if (chatId() === id) drafts.set(id, d); },
      localDraft() { return drafts.get(id); },
      discardDraft() { drafts.remove(id); },
      saves,
      workshop,
      record() { const r = readRecord(); return r && chat().length > 1 ? r : null; },
      blocked() { return chat().length > 1 && !readRecord() ? '开场白后面已经有楼层了：开局只能在只剩开场白时进行。' : null; },
      motion,
      async commit(payload, progress) {
        try { return await commit(id, payload, progress || (() => {})); } catch (e) { return { ok: false, error: (e && e.message) || String(e) }; }
      },
      onClosed() { schedule(); },
      bookStatus,
      bookApply,
    };
  }
  function openOverlay() {
    const page = W.DLOpening;
    if (!page || page.isOpen()) return;
    page.open(hostFor(chatId()));
  }

  // ───────── 跨部换代：斗罗宗门血脉脚本借建档层建传人 ─────────
  // 部、叙事核心、金手指沿用上一代（本体里锁住）；宗门已按兴衰档折算，只改职位。落笔交回 spec.commit（宗门血脉脚本写最新楼层、发换代消息），这里不写 0 楼、不碰世界书。
  // 草稿按聊天另存一份（和开局草稿分开）；同一宗门、同一代、同一兴衰档再打开时接着填。
  const HEIR_PREFIX = 'dl-heir-draft:';
  function openHeir(spec) {
    const page = W.DLOpening;
    if (!page || !spec || !spec.draft || typeof spec.commit !== 'function') return false;
    if (page.isOpen()) page.close();
    const id = chatId(), key = HEIR_PREFIX + id, info = spec.info || {};
    const sig = JSON.stringify([info.宗门, info.代数, info.兴衰档, spec.draft.部]);
    let kept = null;
    try { const t = storage && storage.getItem(key); const o = t ? JSON.parse(t) : null; kept = o && o.sig === sig ? o.d : null; } catch (_) { kept = null; }
    const host = Object.assign({}, hostFor(id), {
      loadDraft: () => kept || spec.draft,
      saveDraft(d) { if (chatId() === id) { try { if (storage) storage.setItem(key, JSON.stringify({ sig, d })); } catch (_) { /* 存不下就算了 */ } } },
      localDraft: () => null,
      discardDraft() { try { if (storage) storage.removeItem(key); } catch (_) { /* 无所谓 */ } },
      saves: null,
      workshop: null,
      record: () => null,
      blocked: () => null,
      async commit(payload, progress) {
        if (chatId() !== id) return { ok: false, error: '聊天已经切换，这次换代取消了。' };
        try {
          const r = await spec.commit(payload, progress || (() => {}));
          if (r && r.ok) host.discardDraft();
          return r;
        } catch (e) { return { ok: false, error: (e && e.message) || String(e) }; }
      },
      onClosed() { schedule(); },
    });
    page.open(host, { draft: kept || spec.draft, heir: info });
    return true;
  }

  // ───────── 0 楼：封面或开局档案卡 ─────────
  let mountedEl = null, mountedSig = '';
  function mount() {
    const el = D.querySelector('#chat .mes[mesid="0"] .mes_text');
    const first = chat()[0];
    const has = !!(first && typeof first.mes === 'string' && first.mes.includes(TOKEN));
    if (!el || el.querySelector('textarea')) return; // 正在编辑
    if (!has) { if (el === mountedEl) { mountedEl = null; mountedSig = ''; } return; }
    const rec = readRecord();
    const n = chat().length;
    const sig = [chatId(), rec && n > 1 ? 'done:' + rec.时间 : 'cover', n > 1 ? 'more' : 'one'].join('|');
    if (el === mountedEl && sig === mountedSig && el.querySelector(':scope > .dlo-mounted')) return;
    mountedEl = el; mountedSig = sig;
    try { W.DLOpening.cover(el, hostFor(chatId())); } catch (e) { console.error(`[${NAME}] 封面画不出来`, e); }
  }
  let timer = 0, observer = null, observed = null;
  function schedule() {
    if (timer) return;
    timer = W.setTimeout(() => { timer = 0; observe(); mount(); }, 40);
  }
  function observe() {
    const target = D.getElementById('chat');
    if (!target || target === observed || typeof W.MutationObserver !== 'function') return;
    if (observer) observer.disconnect();
    observer = new W.MutationObserver(schedule);
    observer.observe(target, { childList: true, subtree: true });
    observed = target;
  }

  // ───────── 重新开局 ─────────
  async function restart() {
    if (chat().length > 1) { notify('开局只能在只剩开场白时进行：请开新聊天，或删掉开场白之后的楼层再点“重新开局”。', 'warning'); return; }
    const rec = readRecord();
    if (rec && rec.提交前变量 && rec.提交前变量.stat_data) {
      if (!(await waitMvu())) { notify('没有找到 MVU，没法还原开局前的变量。', 'error'); return; }
      try {
        await mvu().replaceMvuData(clone(rec.提交前变量), { type: 'message', message_id: 0 });
        if (!drafts.get(chatId()) && rec.草稿) drafts.set(chatId(), rec.草稿);
        notify('0 楼变量已还原成开局前的样子。');
      } catch (e) { notify(`还原变量失败：${(e && e.message) || e}`, 'error'); return; }
    }
    schedule();
    openOverlay();
  }

  // ───────── 启动与卸载 ─────────
  function destroy() {
    for (const s of stops.splice(0)) { try { s(); } catch (_) { /* 已注销 */ } }
    if (observer) observer.disconnect();
    if (timer) W.clearTimeout(timer);
    try { if (W.DLOpening && W.DLOpening.close) W.DLOpening.close(); } catch (_) { /* 已关 */ }
    const el = D.querySelector('#chat .mes[mesid="0"] .mes_text');
    if (el && el.querySelector(':scope > .dlo-mounted')) {
      const first = chat()[0];
      el.textContent = first && typeof first.mes === 'string' ? first.mes : '';
    }
    const style = D.getElementById('dlo-style');
    if (style) style.remove();
    try { if (W[GLOBAL] && W[GLOBAL].destroy === destroy) delete W[GLOBAL]; } catch (_) { /* 主页面已关 */ }
  }
  function start() {
    try { if (W[GLOBAL] && typeof W[GLOBAL].destroy === 'function') W[GLOBAL].destroy(); } catch (_) { /* 旧实例已失效 */ }
    const page = loadPage();
    if (page && page.lib && typeof page.lib.installLuckRuntime === 'function' && !W.__DL_LUCK__) {
      try { page.lib.installLuckRuntime(W, page.lib.LUCK_LIB, page.lib.LUCK_NOTES); } catch (_) { /* ignore */ }
    }
    W[GLOBAL] = { destroy, open: openOverlay, restart, openHeir };
    const onExtSync = () => {
      try { if (W.DLOpening && typeof W.DLOpening.refresh === 'function') W.DLOpening.refresh(); } catch (_) { /* ignore */ }
      schedule();
    };
    for (const evName of ['dl-ext-registry-changed', 'dl-workshop-changed', 'dl-luck-changed']) {
      try { W.addEventListener(evName, onExtSync); stops.push(() => W.removeEventListener(evName, onExtSync)); } catch (_) { /* ignore */ }
    }
    for (const k of Object.keys(EVENTS)) on(k, () => {
      if (k === 'CHAT_CHANGED') { try { W.DLOpening.close(); } catch (_) { /* 无 */ } if (pending && pending.id !== chatId()) pending = null; }
      if (k === 'MESSAGE_SENT') adoptManualSend();
      schedule();
    });
    try {
      const ev = api('getButtonEvent'), eventOn = api('eventOn');
      if (ev && eventOn) { const r = eventOn(ev(RESTART), () => { restart(); }); stops.push(typeof r === 'function' ? r : r && r.stop ? () => r.stop() : () => {}); }
    } catch (_) { /* 没有按钮接口 */ }
    observe();
    mount();
    log('已启动');
  }
  try {
    start();
    window.addEventListener('pagehide', destroy, { once: true });
  } catch (e) { console.error(`[${NAME}] 启动失败`, e); }
})();

// 斗罗远程正文结束
